function dump(node, depth, out) {
  if (depth > 4) return;
  const info = {id: node.id, name: node.name, type: node.type, w: Math.round(node.width), h: Math.round(node.height)};
  if (node.type === 'TEXT') {
    info.chars = node.characters;
    try { info.font = node.fontName; info.size = node.fontSize; } catch(e) { info.font = 'mixed'; }
    try { info.fills = JSON.stringify(node.fills); } catch(e){}
  }
  if ('fills' in node && node.type !== 'TEXT') { try { info.fills = JSON.stringify(node.fills).slice(0,200); } catch(e){} }
  if ('cornerRadius' in node) info.r = node.cornerRadius;
  if ('strokes' in node && node.strokes && node.strokes.length) info.strokes = JSON.stringify(node.strokes).slice(0,150);
  if ('layoutMode' in node && node.layoutMode !== 'NONE') { info.layout = node.layoutMode; info.pad = [node.paddingLeft,node.paddingRight,node.paddingTop,node.paddingBottom]; info.gap = node.itemSpacing; }
  if ('effects' in node && node.effects && node.effects.length) info.effects = JSON.stringify(node.effects).slice(0,200);
  out.push('  '.repeat(depth) + JSON.stringify(info));
  if ('children' in node) for (const c of node.children) dump(c, depth+1, out);
}
