const H = h => { h=h.replace('#',''); const n=parseInt(h,16); return {r:((n>>16)&255)/255,g:((n>>8)&255)/255,b:(n&255)/255}; };
const C = {ink:H('1F2A33'),ink2:H('5B6B76'),ink3:H('94A3AB'),line:H('E3EBE6'),brand:H('88CFA6'),deep:H('2E6B4E'),soft:H('E4F4EB'),white:H('FFFFFF'),gray:H('9AA7AE')};
const solid = c => [{type:'SOLID',color:c}];
async function T(chars, fam, sty, size, color, opt={}) {
  const t = figma.createText();
  t.fontName = {family:fam, style:sty};
  t.characters = chars;
  t.fontSize = size;
  t.fills = solid(color);
  if (opt.lh) t.lineHeight = {value:opt.lh, unit:'PIXELS'};
  if (opt.w) { t.textAutoResize='HEIGHT'; t.resize(opt.w, t.height); }
  if (opt.align) t.textAlignHorizontal = opt.align;
  if (opt.name) t.name = opt.name;
  if (opt.ls) t.letterSpacing = {value:opt.ls, unit:'PIXELS'};
  return t;
}
async function IC(id, color) {
  const comp = await figma.getNodeByIdAsync(id);
  const inst = comp.createInstance();
  if (color) {
    for (const n of inst.findAll(x=>x.fills!==undefined)) {
      try { const f=n.fills; if (Array.isArray(f)&&f.length&&f[0].type==='SOLID') n.fills=[{type:'SOLID',color}]; } catch(e){}
    }
  }
  return inst;
}
function shadow(node, o=0.06) {
  node.effects=[{type:'DROP_SHADOW',color:{r:0.12,g:0.16,b:0.14,a:o},offset:{x:0,y:6},radius:16,spread:0,visible:true,blendMode:'NORMAL'}];
}
