const H = h => { h=h.replace('#',''); const n=parseInt(h,16); return {r:((n>>16)&255)/255,g:((n>>8)&255)/255,b:(n&255)/255}; };
const C = {ink:H('1F2A33'),ink2:H('5B6B76'),ink3:H('94A3AB'),line:H('E3EBE6'),brand:H('88CFA6'),deep:H('2E6B4E'),soft:H('E4F4EB'),white:H('FFFFFF'),gray:H('9AA7AE'),bg1:H('F4FAF6'),bg2:H('FFFFFF')};
