async function T(chars, fam, sty, size, color, opt={}) {
  const t = figma.createText(); t.fontName={family:fam,style:sty}; t.characters=chars; t.fontSize=size; t.fills=solid(color);
  if (opt.lh) t.lineHeight={value:opt.lh,unit:'PIXELS'};
