  if (size) ni.resize(size,size);
  const p = inst.parent; const idx = p.children.indexOf(inst);
  ni.name = inst.name; ni.x = inst.x; ni.y = inst.y;
  p.insertChild(idx, ni);
  inst.remove();
  return ni;
}
function recolor(n, col) {
