const solid = c => [{type:'SOLID',color:c}];
async function T(chars, font, size, color, opts={}) {
  const t = figma.createText();
  t.fontName = {family:font, style:opts.style||'Regular'};
  t.fontSize = size; t.characters = chars; t.fills = solid(color);
  if (opts.lh) t.lineHeight = {value:opts.lh, unit:'PIXELS'};
  if (opts.ls) t.letterSpacing = {value:opts.ls, unit:'PIXELS'};
  if (opts.align) t.textAlignHorizontal = opts.align;
  if (opts.name) t.name = opts.name;
  return t;
}
function card(w,h,r,fill,shadow) {
  const f = figma.createFrame(); f.resize(w,h); f.cornerRadius=r||20;
  f.fills = solid(fill||C.card); f.clipsContent=false;
  if (shadow) f.effects=[{type:'DROP_SHADOW',color:{r:0.11,g:0.16,b:0.14,a:0.06},offset:{x:0,y:4},radius:16,spread:0,visible:true,blendMode:'NORMAL'}];
  return f;
}
function auto(dir, gap) {
  const f = figma.createFrame(); f.layoutMode=dir; f.itemSpacing=gap||0;
  f.primaryAxisSizingMode='AUTO'; f.counterAxisSizingMode='AUTO';
  f.fills=[]; return f;
}
async function iconInst(id, size) {
  const src = await figma.getNodeByIdAsync(id);
  const i = src.createInstance();
  if (size) i.resize(size,size);
  return i;
}
function recolor(n, col) {
  const w = x => { if (x.type==='VECTOR'||x.type==='TEXT') { try{x.fills=solid(col);}catch(e){} } if('children' in x) x.children.forEach(w); };
  w(n);
}
function frame(name, w, h, grad) {
  const f = figma.createFrame(); f.name=name; f.resize(w,h);
  f.fills = grad ? [{type:'GRADIENT_LINEAR',gradientTransform:[[1,0,0],[0,1,0]],gradientStops:grad}] : solid(C.bg);
  f.clipsContent = true;
  return f;
}
async function shell(f, dark) {
  const sb = (await figma.getNodeByIdAsync('1:32')).createInstance();
  sb.x=0; sb.y=0; f.appendChild(sb);
  const hi = (await figma.getNodeByIdAsync('1:42')).createInstance();
