  if (dark) { recolor(sb,{r:1,g:1,b:1}); recolor(hi,{r:1,g:1,b:1}); }
}
async function tabbar(f, current) {
  const tb = (await figma.getNodeByIdAsync('5:5')).createInstance();
  f.appendChild(tb); tb.x=0; tb.y=f.height-84;
  const map = {Today:'Slot_Today',Explore:'Slot_Explore',Journal:'Slot_Journal',Profile:'Slot_Profile'};
  for (const k in map) {
    const slot = tb.findOne(n=>n.name===map[k]);
    const label = slot.findOne(n=>n.type==='TEXT');
    if (k===current) { label.fills=solid(C.brandDeep); label.fontName={family:'Nunito',style:'Bold'}; }
    else label.fills=solid(C.muted);
  }
  return tb;
}
