async function tabbar(f, current) {
  const src = await figma.getNodeByIdAsync('5:5');
  const tb = src.createInstance();
  tb.x = 0; tb.y = f.height - 84 - 20;
  f.appendChild(tb);
  // highlight current
  const map = {Today:'Slot_Today', Explore:'Slot_Explore', Journal:'Slot_Journal', Profile:'Slot_Profile'};
  if (map[current]) {
    const slot = tb.findOne(n=>n.name===map[current]);
    const lbl = slot.findOne(n=>n.name==='Label');
    lbl.fills = solid(C.brandDark); lbl.fontName = NB;
    const ic = slot.findOne(n=>n.type==='INSTANCE');
    ic.setFills ? null : null;
    // recolor icon vectors
    ic.findAll(n=>n.type==='VECTOR').forEach(v=>{ try{v.fills=solid(C.brandDark);}catch(e){} });
  }
  return tb;
}
async function iconBtn(f, iconName, x, y, comp) {
  const src = await figma.getNodeByIdAsync(comp || '1:24');
  return null;
}
async function btn(f, label, w, iconName, style) {
  const src = await figma.getNodeByIdAsync('1:24');
  const b = src.createInstance().detachInstance();
  b.name = 'Btn_' + label.replace(/\s/g,'_');
  b.resize(w, 56);
  const txt = b.findOne(n=>n.type==='TEXT');
  txt.characters = label;
  if (style === 'outline') {
    b.fills = solid(C.white);
    b.strokes = solid(C.brand); b.strokeWeight = 1.5;
    txt.fills = solid(C.brandDark);
  } else if (style === 'soft') {
    b.fills = solid(C.tint);
    txt.fills = solid(C.brandDark);
  }
  // icon slot
  if (iconName) {
    const ic = await icon(iconName, 20);
    ic.findAll(n=>n.type==='VECTOR').forEach(v=>{ try{ v.fills = solid(style==='outline'||style==='soft'?C.brandDark:C.white); }catch(e){} });
    b.insertChild(1, ic);
    ic.layoutAlign = undefined;
    // place before text: reorder
    const idx = b.children.indexOf(txt);
    b.insertChild(idx, ic);
    b.itemSpacing = 8;
  }
  f.appendChild(b);
  return b;
}
async function roundIconBtn(f, iconName, size, tint, iconColor) {
