    f.paddingLeft = opts.pl||0; f.paddingRight = opts.pr||0; f.paddingTop = opts.pt||0; f.paddingBottom = opts.pb||0;
    if (opts.primary) f.primaryAxisSizingMode = opts.primary;
    if (opts.counter) f.counterAxisSizingMode = opts.counter;
    f.counterAxisAlignItems = opts.caai || 'MIN';
    f.primaryAxisAlignItems = opts.paa || 'MIN';
  }
