async function btn(f, label, w, iconName, style) {
  const src = await figma.getNodeByIdAsync('1:24');
  const b = src.createInstance().detachInstance();
  b.name = 'Btn_' + label.replace(/\s/g,'_');
  b.resize(w, 56);
  const txt = b.findOne(n=>n.type==='TEXT');
  txt.characters = label;
  if (style === 'outline') {
    b.fills = solid(C.white);
    b.strokes = solid(C.brand); b.strokeWeight = 1.5;
    txt.fills = solid(C.brandDark);
  } else if (style === 'soft') {
    b.fills = solid(C.tint);
    txt.fills = solid(C.brandDark);
  }
  if (iconName) {
    const ic = await icon(iconName, 20);
    ic.findAll(n=>n.type==='VECTOR').forEach(v=>{ try{ v.fills = solid(style==='outline'||style==='soft'?C.brandDark:C.white); }catch(e){} });
    const idx = b.children.indexOf(txt);
    b.insertChild(idx, ic);
    b.itemSpacing = 8;
  }
  f.appendChild(b);
  return b;
}
