const out = [];
function dump(n, ind, depth) {
  let extra = '';
  if (n.type === 'TEXT') extra = ' "' + n.characters.slice(0,25) + '"';
  out.push(ind + n.name + ' (' + n.type + ') ' + Math.round(n.width) + 'x' + Math.round(n.height) + extra);
  if (depth > 0 && 'children' in n) for (const c of n.children) dump(c, ind + '  ', depth - 1);
}
for (const id of ids) {
  const n = await figma.getNodeByIdAsync(id);
  out.push('=== ' + id + ' ' + n.name);
  dump(n, '', 3);
}
return out.join('\n');

