async function T(chars, font, size, color, opts) {
  const t = figma.createText();
  t.fontName = font; t.fontSize = size; t.characters = chars;
  t.fills = solid(color);
  if (opts && opts.w) { t.textAutoResize='HEIGHT'; t.resize(opts.w, 10); }
  if (opts && opts.align) t.textAlignHorizontal = opts.align;
  if (opts && opts.lh) t.lineHeight = {value:opts.lh, unit:'PIXELS'};
  if (opts && opts.ls) t.letterSpacing = {value:opts.ls, unit:'PIXELS'};
  if (opts && opts.name) t.name = opts.name;
  return t;
}
