  if (opts && opts.radius !== undefined) f.cornerRadius = opts.radius;
  if (opts && opts.shadow) f.effects = [{type:'DROP_SHADOW',color:{r:0.12,g:0.2,b:0.15,a:0.08},offset:{x:0,y:4},radius:16,spread:0,visible:true,blendMode:'NORMAL'}];
  if (opts && opts.layout) {
